import {
  Group,
  BoxGeometry,
  PlaneGeometry,
  Mesh,
  MeshPhysicalNodeMaterial,
  DirectionalLight,
  AmbientLight,
  AdditiveBlending,
  Color,
} from 'three/webgpu';
import { uv, vec2, vec3, mix, smoothstep, time, uniform } from 'three/tsl';
import { gsap } from 'gsap';
import { Primitives } from '@/primitives';
// (No text import – no text content)

/**
 * Creates a compact stat tile (metric card) for the Hub Home.
 * @param {Object} config - PrismNode configuration.
 * @param {Object} ctx - Runtime surface.
 * @returns {THREE.Group}
 */
export default function createNode(config, ctx) {
  const group = new Group();
  const { THREE } = ctx;

  // ─────────────── Lights (added to the group) ───────────────
  // Ambient fill (provided by scene, but we add a local fill for safety)
  const ambient = new AmbientLight(0x0b0b10, 0.6); // surface color with low intensity
  group.add(ambient);

  // Key light: warm, from 30° left
  const key = new DirectionalLight(0xe8ecf2, 1.2);
  key.position.set(2.5, 3, 4);
  key.target.position.set(0, 0, 0);
  group.add(key);
  group.add(key.target);

  // Rim light: slightly cool, from back-right
  const rim = new DirectionalLight(0x16161d, 0.8);
  rim.position.set(-3, 1, -4);
  rim.target.position.set(0, 0, 0);
  group.add(rim);
  group.add(rim.target);

  // Accent edge highlight: red tint
  const accentLight = new DirectionalLight(0xff2a38, 0.4);
  accentLight.position.set(0, 2, 2);
  accentLight.target.position.set(-0.9, 0.4, 0);
  group.add(accentLight);
  group.add(accentLight.target);

  // ─────────────── Card body (machined metal plate) ───────────────
  const cardGeo = new BoxGeometry(2.0, 1.2, 0.12);
  const cardMat = new MeshPhysicalNodeMaterial({
    color: 0x0b0b10,              // surface
    metalness: 0.5,
    roughness: 0.4,
    clearcoat: 0.2,
    envMapIntensity: 0.6,
    // Brushed anisotropy approximation: add a slight anisotropy via normal? Not needed.
  });
  const card = new Mesh(cardGeo, cardMat);
  card.position.set(0, 0, 0);
  group.add(card);

  // Accent edge: thin strip on left side
  const edgeGeo = new BoxGeometry(0.03, 1.0, 0.14);
  const edgeMat = new MeshPhysicalNodeMaterial({
    color: 0xff2a38,
    metalness: 0.3,
    roughness: 0.6,
    emissive: 0xff2a38,
    emissiveIntensity: 0.2,
  });
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.set(-1.0, 0, 0);
  group.add(edge);

  // ─────────────── Gear decoration (loaded from GLB) ───────────────
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const gear = gltf.scene;
      gear.scale.set(0.35, 0.35, 0.35);
      gear.position.set(0, 0.15, 0.1);
      gear.rotation.x = -Math.PI / 2;
      // Make the gear materials match the machined look
      gear.traverse((child) => {
        if (child.isMesh) {
          if (child.material) {
            const mat = child.material;
            mat.color = new Color(0x0b0b10);
            mat.metalness = 0.7;
            mat.roughness = 0.3;
            mat.clearcoat = 0.15;
            mat.needsUpdate = true;
          }
        }
      });
      group.add(gear);
    }).catch((err) => {
      console.warn('Stat tile gear load failed:', err);
    });
  }

  // ─────────────── Contact shadow plane ───────────────
  const shadowGeo = new PlaneGeometry(2.4, 1.6);
  const shadowMat = new MeshPhysicalNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.4,
    blending: AdditiveBlending,
    depthWrite: false,
  });
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -0.65, 0);
  group.add(shadow);

  // ─────────────── Cinematic primitive ───────────────
  let primitivesCleanup = [];
  if (config.cinematicPrimitives && ctx.primitives) {
    config.cinematicPrimitives.forEach((p) => {
      if (p.name === 'parallax-scroll') {
        const result = ctx.primitives['parallax-scroll'](group, p.params);
        if (result.cleanup) primitivesCleanup.push(result.cleanup);
      }
    });
  }

  // ─────────────── Hover & Click interactions ───────────────
  const tl = gsap.timeline({ paused: true });

  const handlers = {
    pointerover: (e) => {
      // Rise-in: subtle lift
      tl.clear();
      tl.to(group.position, {
        y: 1.6 + 0.15,
        duration: 0.5,
        ease: 'power3.out',
      });
      tl.play();
    },
    pointerout: (e) => {
      tl.clear();
      tl.to(group.position, {
        y: 1.6,
        duration: 0.5,
        ease: 'power3.out',
      });
      tl.play();
    },
    pointerdown: (e) => {
      // Press-down
      gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(2)',
        overwrite: 'auto',
      });
      // Emit event
      if (ctx.emit) {
        ctx.emit('hub-home.select', { target: group });
      }
    },
    pointerup: (e) => {
      gsap.to(group.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.3,
        ease: 'power4.out',
        overwrite: 'auto',
      });
    },
  };
  group.userData.handlers = handlers;

  // ─────────────── Cleanup function ───────────────
  group.userData.cleanup = () => {
    // Kill GSAP timelines
    tl.kill();
    // Remove event handlers
    delete group.userData.handlers;
    // Dispose primitive effects
    primitivesCleanup.forEach((fn) => fn());
    // Dispose geometries and materials
    card.geometry.dispose();
    card.material.dispose();
    edge.geometry.dispose();
    edge.material.dispose();
    shadow.geometry.dispose();
    shadow.material.dispose();
    // Remove children (GLB will be disposed by loader cache)
    while (group.children.length > 0) {
      const child = group.children[0];
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
      group.remove(child);
    }
  };

  return group;
}
